local SSLogger = {}
SSLogger.__index = SSLogger

function SSLogger.new(player: Player): SSLogger
	local loggerManagerIns = game.ReplicatedStorage.Packages.LoggerManager
	local SLoggerIns = loggerManagerIns.SLogger.SLogger:Clone()
	local self = require(SLoggerIns)
	self.Init(player.UserId, require(loggerManagerIns), require(loggerManagerIns.SLogger.SystemNameCache))
	SLoggerIns:Destroy()
	return self
end

return SSLogger
